import { describe, expect, it } from "@jest/globals";
import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { assignExperiment } from "../src/evaluate.js";
import { BUCKET_COUNT, bucketFor, inTrafficAllocation } from "../src/hashing.js";
import type { ExperimentDefinition } from "../src/types.js";

/**
 * Cross-surface parity: the browser SDK (spectry-js), this SDK and the PHP SDK
 * must put the same visitor in the same variation.
 *
 * `fixtures/experiment-bucketing.json` is generated by spectry-js
 * (`tests/vectors/generate-bucketing-vectors.cjs`) from the browser's own
 * bucketing and is pinned, byte for byte, by all three test suites. A failing
 * vector means this SDK drifted from the browser. Fix the drift; never
 * regenerate or edit the file to make this pass.
 */
interface Vector {
  visitorId: string;
  experimentId: string;
  trafficSplit: number;
  variations: Array<{ id: string; weight?: number }>;
  buckets: { variant: number; traffic: number };
  inTraffic: boolean;
  variationId: string | null;
}

const FIXTURE = resolve(process.cwd(), "test/fixtures/experiment-bucketing.json");
const raw = readFileSync(FIXTURE, "utf8");
const { vectors, bucketCount } = JSON.parse(raw) as { vectors: Vector[]; bucketCount: number };

const definition = (v: Vector): ExperimentDefinition =>
  ({
    id: v.experimentId,
    name: v.experimentId,
    test_type: "visual",
    target_url: "",
    traffic_split: v.trafficSplit,
    targeting_rules: {},
    variations: v.variations.map((variation) => ({ ...variation, name: variation.id })),
  }) as unknown as ExperimentDefinition;

describe("shared bucketing vectors (browser ↔ Node ↔ PHP)", () => {
  it("has 1,000 vectors over the same bucket space", () => {
    expect(vectors).toHaveLength(1000);
    expect(bucketCount).toBe(BUCKET_COUNT);
  });

  it("reproduces every traffic and variant bucket", () => {
    for (const v of vectors) {
      expect([v.visitorId, bucketFor(v.visitorId, v.experimentId, "variant")]).toEqual([
        v.visitorId,
        v.buckets.variant,
      ]);
      expect([v.visitorId, bucketFor(v.visitorId, v.experimentId, "traffic")]).toEqual([
        v.visitorId,
        v.buckets.traffic,
      ]);
      expect(inTrafficAllocation(v.visitorId, v.experimentId, v.trafficSplit)).toBe(v.inTraffic);
    }
  });

  it("assigns the same variation as the browser for every vector", () => {
    for (const v of vectors) {
      const assignment = assignExperiment(definition(v), {}, v.visitorId);
      expect([v.visitorId, v.experimentId, assignment?.variationId ?? null]).toEqual([
        v.visitorId,
        v.experimentId,
        v.variationId,
      ]);
    }
  });

  it("is the same file spectry-js generated, when the sibling repo is checked out", () => {
    const origin = resolve(process.cwd(), "../../spectry-js/tests/vectors/experiment-bucketing.json");
    if (!existsSync(origin)) return; // CI checks out this repo alone.
    expect(readFileSync(origin, "utf8")).toBe(raw);
  });
});
